import React, { useMemo, useRef } from 'react';
import * as THREE from 'three';
import { useFrame, useLoader } from '@react-three/fiber';
import { Text } from '@react-three/drei';

/**
 * A 3D display board / stand that shows the garment image as a texture
 * on a flat panel, positioned in the room like a fashion display.
 */
const DressDisplayBoard = ({
    imageUrl,
    productName = 'Select a Dress',
    position = [-2, 0.5, -1],
}) => {
    const frameRef = useRef();

    // Load the garment texture
    const texture = useMemo(() => {
        if (!imageUrl) return null;
        const loader = new THREE.TextureLoader();
        const tex = loader.load(imageUrl);
        tex.colorSpace = THREE.SRGBColorSpace;
        return tex;
    }, [imageUrl]);

    // Subtle floating animation for the display
    useFrame((state) => {
        if (frameRef.current) {
            frameRef.current.position.y =
                position[1] + Math.sin(state.clock.elapsedTime * 0.6 + 1) * 0.02;
        }
    });

    return (
        <group ref={frameRef} position={position}>
            {/* Display stand base */}
            <mesh position={[0, -1.95, 0]} castShadow>
                <cylinderGeometry args={[0.4, 0.45, 0.08, 24]} />
                <meshStandardMaterial color="#2c2c2c" metalness={0.7} roughness={0.3} />
            </mesh>

            {/* Stand pole */}
            <mesh position={[0, -1, 0]} castShadow>
                <cylinderGeometry args={[0.03, 0.03, 1.9, 12]} />
                <meshStandardMaterial color="#c9a96e" metalness={0.8} roughness={0.2} />
            </mesh>

            {/* Frame border — outer */}
            <mesh position={[0, 0.3, 0]} castShadow>
                <boxGeometry args={[1.65, 2.15, 0.06]} />
                <meshStandardMaterial color="#1a1a1a" metalness={0.5} roughness={0.4} />
            </mesh>

            {/* Frame inner accent */}
            <mesh position={[0, 0.3, 0.025]}>
                <boxGeometry args={[1.55, 2.05, 0.02]} />
                <meshStandardMaterial color="#c9a96e" metalness={0.7} roughness={0.3} />
            </mesh>

            {/* Image surface */}
            <mesh position={[0, 0.3, 0.04]}>
                <planeGeometry args={[1.4, 1.8]} />
                {texture ? (
                    <meshStandardMaterial
                        map={texture}
                        roughness={0.5}
                        metalness={0}
                    />
                ) : (
                    <meshStandardMaterial color="#f0eeea" roughness={0.8} />
                )}
            </mesh>

            {/* Product name label */}
            <Text
                position={[0, -0.75, 0.05]}
                fontSize={0.08}
                color="#333333"
                maxWidth={1.3}
                textAlign="center"
                anchorY="top"
                font="https://fonts.gstatic.com/s/inter/v18/UcC73FwrK3iLTeHuS_fvQtMwCp50KnMa2JL7W0Q5nw.woff2"
            >
                {productName}
            </Text>

            {/* Spotlight targeting the display */}
            <spotLight
                position={[0, 2.5, 1.5]}
                target-position={[0, 0.3, 0]}
                angle={0.4}
                penumbra={0.6}
                intensity={1.2}
                color="#fff8ee"
            />
        </group>
    );
};

export default DressDisplayBoard;
