import React from 'react';
import { Environment, ContactShadows } from '@react-three/drei';

const SceneEnvironment = () => {
    return (
        <>
            {/* Ambient environment lighting — studio preset gives soft, even illumination */}
            <Environment preset="studio" background={false} />

            {/* Contact shadows beneath the mannequin for grounding */}
            <ContactShadows
                position={[0, -1.5, 0]}
                opacity={0.4}
                scale={10}
                blur={2.5}
                far={4}
                color="#1a1a2e"
            />

            {/* Key light — warm spotlight from upper-right */}
            <spotLight
                position={[5, 8, 5]}
                angle={0.3}
                penumbra={0.8}
                intensity={1.5}
                color="#fff5e6"
                castShadow
                shadow-mapSize={[1024, 1024]}
            />

            {/* Fill light — cool, softer from the left */}
            <spotLight
                position={[-4, 6, 3]}
                angle={0.4}
                penumbra={1}
                intensity={0.8}
                color="#e6f0ff"
            />

            {/* Rim/back light — subtle highlight from behind */}
            <pointLight position={[0, 4, -5]} intensity={0.4} color="#ffd6e0" />

            {/* Ambient fill to prevent fully dark shadows */}
            <ambientLight intensity={0.3} color="#f0f0f5" />
        </>
    );
};

export default SceneEnvironment;
